function design(site, analyse) {
  const xs = [
    0, 4.918, 9.836, 14.755, 19.673, 24.591,
    29.509, 34.427, 39.345, 44.264, 49.182, 54.1
  ];
  const yBottom = -7.30;
  const zLeft = -4.35;
  const zRight = 4.35;

  // Each group is ordered from heavier to lighter candidates.
  const sections = [
    [ // top chords
      "S460 CHS406.4x12.5",
      "S460 CHS355.6x12.5",
      "S460 CHS323.9x10",
      "S460 CHS273x10"
    ],
    [ // bottom chords
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8"
    ],
    [ // verticals
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8"
    ],
    [ // crossed side webs
      "S460 CHS355.6x12.5",
      "S460 CHS323.9x10",
      "S460 CHS273x10",
      "S460 CHS244.5x8",
      "S460 CHS219.1x8"
    ],
    [ // transverse ties
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8",
      "S460 CHS168.3x6.3",
      "S460 CHS139.7x6.3"
    ],
    [ // top and bottom plan bracing
      "S460 CHS244.5x8",
      "S460 CHS219.1x8",
      "S460 CHS193.7x8",
      "S460 CHS168.3x6.3",
      "S460 CHS139.7x6.3",
      "S460 CHS114.3x5"
    ]
  ];

  const note =
    "Deep pinned twin side trusses use crossed webs and triangulated top and bottom planes; section sizes are reduced only while analysis retains margin.";

  function build(sel) {
    const nodes = [];
    const members = [];
    const spec = (group) => sections[group][sel[group]];
    const add = (a, b, group) => members.push([a, b, spec(group)]);

    for (let i = 0; i < xs.length; i++) {
      nodes.push({ id: "BL" + i, x: xs[i], y: yBottom, z: zLeft, joint: "pin" });
      nodes.push({ id: "BR" + i, x: xs[i], y: yBottom, z: zRight, joint: "pin" });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      // Two upper and two lower longitudinal chords.
      add("L" + i, "L" + (i + 1), 0);
      add("R" + i, "R" + (i + 1), 0);
      add("BL" + i, "BL" + (i + 1), 1);
      add("BR" + i, "BR" + (i + 1), 1);

      // Crossed web members in each vertical side truss.
      add("L" + i, "BL" + (i + 1), 3);
      add("BL" + i, "L" + (i + 1), 3);
      add("R" + i, "BR" + (i + 1), 3);
      add("BR" + i, "R" + (i + 1), 3);

      // One diagonal in each top and bottom plan panel.
      add("L" + i, "R" + (i + 1), 5);
      add("BL" + i, "BR" + (i + 1), 5);
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, 2);
      add("R" + i, "BR" + i, 2);
      add("L" + i, "R" + i, 4);
      add("BL" + i, "BR" + i, 4);
    }

    return { note, nodes, members };
  }

  function hasMargin(r) {
    if (!r || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.78) return false;
    if (typeof r.alpha_crMin === "number" && r.alpha_crMin < 5.7) return false;
    if (typeof r.frequency === "number" && r.frequency < 1.26) return false;

    if (typeof r.sag === "number" && typeof r.sagLimit === "number" &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.82) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.82) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;
    return true;
  }

  let calls = 0;
  const callLimit = 40;
  let bestSafe = null;
  let bestOk = null;

  function evaluate(sel) {
    if (calls >= callLimit) return null;
    const d = build(sel);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }
    if (!r || r.error) return null;

    const rec = { d, sel: sel.slice(), r };
    if (r.ok === true && typeof r.mass === "number" &&
        (!bestOk || r.mass < bestOk.r.mass)) bestOk = rec;
    if (hasMargin(r) && typeof r.mass === "number" &&
        (!bestSafe || r.mass < bestSafe.r.mass)) bestSafe = rec;
    return rec;
  }

  let current = sections.map(() => 0);
  evaluate(current);

  // Greedily reduce each member group, then make a second pass to use any
  // margin created by the reductions in the other groups.
  for (let pass = 0; pass < 2 && calls < callLimit; pass++) {
    let changed = false;

    for (let g = 0; g < sections.length && calls < callLimit; g++) {
      let bestForGroup = null;

      for (let j = current[g] + 1; j < sections[g].length && calls < callLimit; j++) {
        const trial = current.slice();
        trial[g] = j;
        const rec = evaluate(trial);
        if (rec && hasMargin(rec.r) &&
            (!bestForGroup || rec.r.mass < bestForGroup.r.mass)) {
          bestForGroup = rec;
        }
      }

      if (bestForGroup) {
        current = bestForGroup.sel;
        changed = true;
      }
    }

    if (!changed) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestOk) return bestOk.d;
  return build(sections.map(() => 0));
}

function design(site, analyse) {
