          "114.3x5", "88.9x5"]),
    s460(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5"]),
    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
