    s460(["323.9x10", "273x10", "244.5x8", "219.1x8",
          "193.7x8", "193.7x6.3", "168.3x6.3", "139.7x6.3",
          "114.3x5", "88.9x5", "76.1x4"]),
    s460(["273x10", "244.5x8", "219.1x8", "193.7x8",
          "193.7x6.3", "168.3x6.3", "139.7x6.3", "114.3x5",
          "88.9x5", "76.1x4"]),
    s460(["406.4x12.5", "355.6x12.5", "323.9x10", "273x10",
          "244.5x8", "219.1x8", "193.7x8", "193.7x6.3",
          "168.3x6.3", "139.7x6.3", "114.3x5"])
  ];

  const note =
    "I added alternating transverse-frame diagonals to close the 3-D panels, used single solid side webs, and pruned sections only while the published-case analysis retained margin.";

  function build(sel) {
    const nodes = [];
    const members = [];
    const add = (a, b, group) =>
      members.push([a, b, sections[group][sel[group]]]);

    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "BL" + i, x: xs[i], y: yBottom, z: zLeft, joint: "pin"
      });
      nodes.push({
        id: "BR" + i, x: xs[i], y: yBottom, z: zRight, joint: "pin"
      });
    }

    for (let i = 0; i < xs.length - 1; i++) {
      const outer = i < 3 || i > 7;
      const upperGroup = outer ? 0 : 1;
      const lowerGroup = outer ? 2 : 3;

      add("L" + i, "L" + (i + 1), upperGroup);
      add("R" + i, "R" + (i + 1), upperGroup);
      add("BL" + i, "BL" + (i + 1), lowerGroup);
      add("BR" + i, "BR" + (i + 1), lowerGroup);

      // One compression-capable diagonal in each side-truss panel.
      add("L" + i, "BL" + (i + 1), 5);
      add("R" + i, "BR" + (i + 1), 5);

      // Triangulate the top and bottom longitudinal planes.
      add("L" + i, "R" + (i + 1), 8);
      add("BL" + i, "BR" + (i + 1), 9);
    }

    for (let i = 0; i < xs.length; i++) {
      add("L" + i, "BL" + i, 4);
      add("R" + i, "BR" + i, 4);
      add("L" + i, "R" + i, 6);
      add("BL" + i, "BR" + i, 7);

      // A diagonal closes every transverse frame; alternate its orientation.
      if (i % 2 === 0) add("L" + i, "BR" + i, 10);
      else add("R" + i, "BL" + i, 10);
    }

    return { note, nodes, members };
  }

  function passesMargin(r) {
    if (!r || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.70) return false;

    const cr = Number.isFinite(r.alpha_crMin)
      ? r.alpha_crMin
      : (Number.isFinite(r.alpha_cr) ? r.alpha_cr : null);
    if (cr !== null && cr < 7.5) return false;

    const f = Number.isFinite(r.frequency)
      ? r.frequency
      : (Number.isFinite(r.fMin) ? r.fMin : null);
    if (f !== null && f < 1.30) return false;

    if (Number.isFinite(r.sag) && Number.isFinite(r.sagLimit) &&
        r.sagLimit > 0 && r.sag / r.sagLimit > 0.78) return false;
    if (Number.isFinite(r.sway) && Number.isFinite(r.swayLimit) &&
        r.swayLimit > 0 && r.sway / r.swayLimit > 0.78) return false;

    if (Number.isFinite(r.fatigueWorst) && r.fatigueWorst > 0.82) return false;
    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;

    return true;
  }

  let calls = 0;
  const callLimit = 128;
  let bestSafe = null;
  let bestOk = null;

  function evaluate(sel) {
    if (calls >= callLimit) return null;

    const d = build(sel);
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      return null;
    }

    if (!r || r.error) return null;
    const rec = { d, sel: sel.slice(), r };

    if (r.ok === true && typeof r.mass === "number" &&
        (!bestOk || r.mass < bestOk.r.mass)) {
      bestOk = rec;
    }
    if (passesMargin(r) && typeof r.mass === "number" &&
        (!bestSafe || r.mass < bestSafe.r.mass)) {
      bestSafe = rec;
    }
    return rec;
  }

  let current = sections.map(() => 0);
  evaluate(current);

  // Greedy section reduction, followed by a refinement pass.
  for (let pass = 0; pass < 2 && calls < callLimit; pass++) {
    let changed = false;

    for (let g = 0; g < sections.length && calls < callLimit; g++) {
      let bestForGroup = null;

      for (let j = current[g] + 1;
           j < sections[g].length && calls < callLimit;
           j++) {
        const trial = current.slice();
        trial[g] = j;
        const rec = evaluate(trial);

        if (rec && passesMargin(rec.r) &&
            (!bestForGroup || rec.r.mass < bestForGroup.r.mass)) {
          bestForGroup = rec;
        }
      }

      if (bestForGroup) {
        current = bestForGroup.sel.slice();
        changed = true;
      }
    }

    if (!changed) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestOk) return bestOk.d;
  return build(current);
}

function design(site, analyse) {
  const xs = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const H = 7.5;
  const halfW = 4.35;

  const nodes = [];
  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: "C" + i, x: xs[i], y: -H, z: 0, joint: "pin" });
  }

  const mem = [];
  function add(a, b, g) {
    mem.push({ a, b, g });
  }

  // Top longitudinal chords (deck edge beams)
  for (let i = 0; i < 11; i++) {
    const d = Math.min(i, 10 - i);
    add("L" + i, "L" + (i + 1), "top" + d);
    add("R" + i, "R" + (i + 1), "top" + d);
  }

  // Bottom central chord
  for (let i = 0; i < 11; i++) {
    const d = Math.min(i, 10 - i);
    add("C" + i, "C" + (i + 1), "bot" + d);
  }

  // Top cross beams
  for (let i = 0; i < 12; i++) {
    add("L" + i, "R" + i, "cross");
  }

  // Inclined transverse struts to the central lower chord
  for (let i = 0; i < 12; i++) {
    const d = Math.min(i, 11 - i);
    add("L" + i, "C" + i, "strut" + d);
    add("R" + i, "C" + i, "strut" + d);
  }

  // Side diagonals, Warren-like, with both end bottom nodes anchored
  for (let i = 0; i < 11; i++) {
    const g = "diag" + Math.min(i, 10 - i);
    if (i === 10) {
      add("L10", "C11", g);
      add("R10", "C11", g);
    } else if (i % 2 === 0) {
      add("L" + (i + 1), "C" + i, g);
      add("R" + (i + 1), "C" + i, g);
    } else {
      add("L" + i, "C" + (i + 1), g);
      add("R" + i, "C" + (i + 1), g);
    }
  }

  // Top-plan bracing between deck lines
  for (let i = 0; i < 11; i++) {
    if (i % 2 === 0) {
      add("L" + i, "R" + (i + 1), "plan");
    } else {
      add("R" + i, "L" + (i + 1), "plan");
    }
  }

  const specs = [
    "S690 CHS48.3x3.2",
    "S690 CHS60.3x4",
    "S690 CHS76.1x4",
    "S690 CHS88.9x4",
    "S690 CHS88.9x5",
    "S690 CHS114.3x4",
    "S690 CHS114.3x5",
    "S690 CHS139.7x5",
    "S690 CHS168.3x5",
    "S690 CHS139.7x6.3",
    "S690 CHS168.3x6.3",
    "S690 CHS193.7x6.3",
    "S690 CHS193.7x8",
    "S690 CHS219.1x8",
    "S690 CHS244.5x8",
    "S690 CHS273x10",
    "S690 CHS323.9x10",
    "S690 CHS355.6x12.5",
    "S690 CHS406.4x12.5",
    "S690 CHS457x16"
  ];

  const groups = Array.from(new Set(mem.map(m => m.g)));

  function copyMap(m) {
    const o = {};
    for (const g of groups) o[g] = m[g];
    return o;
  }

  function build(assign) {
    return {
      note: "S690 triangular under-deck space truss with central lower chord and top-plan bracing.",
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
      members: mem.map(m => [m.a, m.b, assign[m.g]])
    };
  }

  let calls = 0;
  const cache = new Map();

  function evaluate(assign) {
    const key = groups.map(g => assign[g]).join("|");
    if (cache.has(key)) return cache.get(key);
    if (calls >= 400) return null;
    calls++;
    const d = build(assign);
    const r = analyse(d);
    cache.set(key, r);
    return r;
  }

  function acceptable(r) {
    if (!r || r.error || r.ok !== true) return false;

    const util = Number(r.maxUtil);
    if (isFinite(util) && util > 0.60) return false;

    const fat = Number(r.fatigueWorst);
    if (isFinite(fat) && fat > 0.65) return false;

    const acr = Number(r.alphaCr);
    if (isFinite(acr) && acr > 0 && acr < 7.5) return false;

    const f = Number(r.frequency);
    if (isFinite(f) && f > 0 && f < 1.35) return false;

    if (r.sagLimit && r.sag && Number(r.sag) > 0.80 * Number(r.sagLimit)) return false;
    if (r.swayLimit && r.sway && Number(r.sway) > 0.80 * Number(r.swayLimit)) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  let bestSafeMap = null;
  let bestSafeMass = Infinity;
  let bestSafeRes = null;

  let bestAnyMap = null;
  let bestAnyMass = Infinity;
  let bestAnyRes = null;

  function run(assign) {
    const r = evaluate(assign);
    if (r && r.ok === true) {
      const mass = Number(r.mass);
      const mm = isFinite(mass) ? mass : Infinity;
      if (mm < bestAnyMass) {
        bestAnyMass = mm;
        bestAnyMap = copyMap(assign);
        bestAnyRes = r;
      }
      if (acceptable(r) && mm < bestSafeMass) {
        bestSafeMass = mm;
        bestSafeMap = copyMap(assign);
        bestSafeRes = r;
      }
    }
    return r;
  }

  const initMap = {};
  const maxSpec = specs[specs.length - 1];
  for (const g of groups) initMap[g] = maxSpec;

  run(initMap);

  // Coordinate descent using binary search on the sorted section list.
  for (let pass = 0; pass < 3 && calls < 395; pass++) {
    let changed = false;

    for (const g of groups) {
      if (calls >= 395) break;

      const current = initMap[g] ? initMap[g] : maxSpec;
      let localCurrent = current;
      // Use the actual evolving map, not initMap.  Keep a local copy only for fallback.
      localCurrent = bestSafeMap && bestSafeMap[g] ? bestSafeMap[g] : (initMap ? initMap[g] : maxSpec);

      // The map is initialized below if absent.
      if (!globalThis.__dummyKardashevMap) {
        // no-op; kept deliberately simple
      }

      // Ensure the evolving map exists.
      if (typeof design._map === "undefined") {
        design._map = copyMap(initMap);
      }
      const map = design._map;

      const old = map[g];

      let lo = 0;
      let hi = specs.length - 1;
      let best = -1;
      let bestResLocal = null;

      while (lo <= hi && calls < 395) {
        const mid = (lo + hi) >> 1;
        map[g] = specs[mid];
        const r = run(map);
        if (acceptable(r)) {
          best = mid;
          bestResLocal = r;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (best >= 0) {
        map[g] = specs[best];
        if (specs[best] !== old) changed = true;
      } else {
        map[g] = old;
      }
    }

    if (!changed) break;
  }

  let chosenMap = bestSafeMap || bestAnyMap || initMap;
  let chosenRes = bestSafeMap ? bestSafeRes : (bestAnyMap ? bestAnyRes : null);

  const out = build(chosenMap);
  const approxMass = chosenRes && chosenRes.mass ? Math.round(Number(chosenRes.mass)) : 0;
  out.note = "S690 triangular under-deck space truss with a central lower chord and top-plan bracing; nominal mass approx " + approxMass + " kg.";
  return out;
}

