    const fat = Number(r.fatigueWorst);
    if (isFinite(fat) && fat > 0.80) return false;

    const acr = Number(r.alphaCr);
    if (isFinite(acr) && acr > 0 && acr < 6.0) return false;

    const f = Number(r.frequency);
    if (isFinite(f) && f > 0 && f < 1.25) return false;

    if (r.sagLimit && r.sag && Number(r.sag) > 0.90 * Number(r.sagLimit)) return false;
    if (r.swayLimit && r.sway && Number(r.sway) > 0.90 * Number(r.swayLimit)) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  let best = null;

  function record(topo, specs, r) {
    if (!r || !safe(r)) return;
    const m = Number(r.mass);
    if (!isFinite(m)) return;
    if (!best || m < best.mass) {
      best = { topo: topo, specs: specs.slice(), mass: m, res: r };
    }
  }

  let currentSpecs = baseTopo.initSpecs.slice();
  let currentRes = evalSpecs(baseTopo, currentSpecs);
  record(baseTopo, currentSpecs, currentRes);

  for (let pass = 0; pass < 2; pass++) {
    if (calls >= LIMIT) break;
    let changed = false;
    const order = baseTopo.pairs.map((p, i) => i)
      .filter(i => currentSpecs[i])
      .sort((i, j) => massPerM(currentSpecs[j]) * baseLengths[j] - massPerM(currentSpecs[i]) * baseLengths[i]);

    for (const i of order) {
      if (calls >= LIMIT) break;
      const spec = currentSpecs[i];
      if (!spec || !spec.startsWith("S690")) continue;
      const ci = steelIdx[spec];
      if (ci === undefined || ci <= 0) continue;

      const trial = currentSpecs.slice();
      trial[i] = steelList[ci - 1];
      const r = evalSpecs(baseTopo, trial);
      if (r && safe(r)) {
        currentSpecs = trial;
        currentRes = r;
        changed = true;
        record(baseTopo, currentSpecs, currentRes);
      }
    }
    if (!changed) break;
  }

  let order2 = baseTopo.pairs.map((p, i) => i)
    .filter(i => currentSpecs[i] && currentSpecs[i].startsWith("S690") && steelIdx[currentSpecs[i]] > 0)
    .sort((i, j) => massPerM(currentSpecs[j]) * baseLengths[j] - massPerM(currentSpecs[i]) * baseLengths[i]);

  for (const i of order2) {
    if (calls >= LIMIT - 25) break;
    const ci = steelIdx[currentSpecs[i]];
    if (ci === undefined || ci <= 0) continue;

    let lo = 0;
    let hi = ci - 1;
    let bestIdx = ci;
    let bestRes = null;

    while (lo <= hi && calls < LIMIT - 25) {
      const mid = (lo + hi) >> 1;
      const trial = currentSpecs.slice();
      trial[i] = steelList[mid];
      const r = evalSpecs(baseTopo, trial);
      if (r && safe(r)) {
        bestIdx = mid;
        bestRes = r;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    if (bestIdx < ci && bestRes) {
      const trial = currentSpecs.slice();
      trial[i] = steelList[bestIdx];
      currentSpecs = trial;
      currentRes = bestRes;
      record(baseTopo, currentSpecs, currentRes);
    }
  }

  function currentUtilMap(topo, specs, res) {
    const active = [];
    for (let i = 0; i < specs.length; i++) if (specs[i]) active.push(i);
    const util = {};
    if (res && res.members) {
      const n = Math.min(active.length, res.members.length);
      for (let k = 0; k < n; k++) {
        util[active[k]] = Number(res.members[k] && res.members[k].util !== undefined ? res.members[k].util : 0);
      }
    }
    return util;
  }

  let util = currentUtilMap(baseTopo, currentSpecs, currentRes);
  let candidates = [];

  for (let i = 0; i < currentSpecs.length; i++) {
    if (!currentSpecs[i]) continue;
    const role = (i >= 33 && i <= 44) || (i >= 45 && i <= 68) || (i >= 69 && i <= 90) || (i >= 91 && i <= 101);
    if (!role) continue;
    const u = util[i] !== undefined ? util[i] : 1.0;
    if (u < 0.45) candidates.push(i);
  }

  candidates.sort((i, j) => {
    const ui = util[i] !== undefined ? util[i] : 0;
    const uj = util[j] !== undefined ? util[j] : 0;
    if (Math.abs(ui - uj) > 0.001) return ui - uj;
    return massPerM(currentSpecs[j]) * baseLengths[j] - massPerM(currentSpecs[i]) * baseLengths[i];
  });

  for (const i of candidates) {
    if (calls >= LIMIT) break;
    const trial = currentSpecs.slice();
    trial[i] = null;
    const r = evalSpecs(baseTopo, trial);
    if (!r || !safe(r)) continue;

    const acr = Number(r.alphaCr);
    if (isFinite(acr) && acr > 0 && acr < 10.0) continue;
    const f = Number(r.frequency);
    if (isFinite(f) && f > 0 && f < 1.35) continue;

    currentSpecs = trial;
    currentRes = r;
    record(baseTopo, currentSpecs, currentRes);
    util = currentUtilMap(baseTopo, currentSpecs, currentRes);
  }

  if (calls < LIMIT - 10) {
    let changed = true;
    while (changed && calls < LIMIT - 5) {
      changed = false;
      const order3 = baseTopo.pairs.map((p, i) => i)
        .filter(i => currentSpecs[i] && currentSpecs[i].startsWith("S690") && steelIdx[currentSpecs[i]] > 0)
        .sort((i, j) => massPerM(currentSpecs[j]) * baseLengths[j] - massPerM(currentSpecs[i]) * baseLengths[i]);

      for (const i of order3) {
        if (calls >= LIMIT - 5) break;
        const ci = steelIdx[currentSpecs[i]];
        if (ci === undefined || ci <= 0) continue;
        const trial = currentSpecs.slice();
        trial[i] = steelList[ci - 1];
        const r = evalSpecs(baseTopo, trial);
        if (r && safe(r)) {
          currentSpecs = trial;
          currentRes = r;
          changed = true;
          record(baseTopo, currentSpecs, currentRes);
        }
      }
    }
  }

  if (best) {
    const specs = best.specs;
    const members = [];
    for (let i = 0; i < best.topo.pairs.length; i++) {
      const s = specs[i];
      if (s) members.push([best.topo.pairs[i].a, best.topo.pairs[i].b, s]);
    }
    return {
      note: "Attempt-2 triangular under-deck space truss refined with individual S690 CHS member sizing and safe removal of low-utilisation redundant bracing.",
      nodes: best.topo.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint || "pin" })),
      members: members
    };
  }

  return {
    note: "Fallback attempt-2 baseline.",
    nodes: baseNodes,
    members: basePairs.map(p => [p[0], p[1], p[2]])
  };
}

function design(site, analyse) {
  // Twin Warren girders below the deck (top chords = deck edge nodes at y=0),
  // bottom chords at y=-H, top and bottom lateral bracing (box action).
  // Every member is sized individually by iterating analyse(): utilisation
  // above 0.85 gets the next larger tube, below 0.60 the next smaller one.
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.4;
  const MAT = "S460 ";
  const SEC = ["CHS33.7x2.6","CHS42.4x3.2","CHS48.3x3.2","CHS60.3x3.2","CHS60.3x4","CHS76.1x3.2",
    "CHS76.1x4","CHS88.9x4","CHS88.9x5","CHS114.3x4","CHS114.3x5","CHS139.7x5","CHS168.3x5",
    "CHS139.7x6.3","CHS168.3x6.3","CHS193.7x6.3","CHS193.7x8","CHS219.1x8","CHS244.5x8",
    "CHS273x10","CHS323.9x10","CHS355.6x12.5","CHS406.4x12.5","CHS457x16"];
  const LAT = ["ST", "TL", "BS", "BB"];
  const CH = ["TC", "BC", "D"];

  // Bottom nodes at mid-panel positions, both edge lines
  const nodes = [];
  for (let i = 0; i <= 10; i++) {
    const xm = (X[i] + X[i + 1]) / 2;
    nodes.push({ id: "BL" + i, x: xm, y: -H, z: ZL, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xm, y: -H, z: ZR, joint: "pin" });
  }

  const mem = [];
  const add = (a, b, g, idx) => mem.push({ a: a, b: b, g: g, idx: idx });

  // Warren diagonals (both trusses)
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "BL" + i, "D", 14);
    add("BL" + i, "L" + (i + 1), "D", 14);
    add("R" + i, "BR" + i, "D", 14);
    add("BR" + i, "R" + (i + 1), "D", 14);
  }
  // Top chords (deck edge lines, compression)
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "L" + (i + 1), "TC", 19);
    add("R" + i, "R" + (i + 1), "TC", 19);
  }
  // Bottom chords (tension)
  for (let i = 0; i <= 9; i++) {
    add("BL" + i, "BL" + (i + 1), "BC", 16);
    add("BR" + i, "BR" + (i + 1), "BC", 16);
  }
  // Top plane: struts at each deck node and one diagonal per panel
  for (let i = 0; i <= 11; i++) add("L" + i, "R" + i, "ST", 7);
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + (i + 1), "TL", 7);
  // Bottom plane: struts and one diagonal per panel
  for (let i = 0; i <= 10; i++) add("BL" + i, "BR" + i, "BS", 7);
  for (let i = 0; i <= 9; i++) add("BL" + i, "BR" + (i + 1), "BB", 7);

  const specOf = (m) => MAT + SEC[m.idx];
  const build = () => {
    const ns = nodes.map((n) => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint }));
    const ms = mem.map((m) => ({ a: m.a, b: m.b, spec: specOf(m) }));
    return {
      note: "Twin Warren girders (depth 7.4 m) at z=±4.35 with top and bottom lateral bracing; S460 tubes sized per member by utilisation.",
      nodes: ns,
      joints: {},
      members: ms
    };
  };

  let best = null;
  let last = null;
  const prevStep = new Array(mem.length).fill(0);

  for (let it = 0; it < 60; it++) {
    const d = build();
    const r = analyse(d);
    if (!r || r.error) break;
    last = d;
    if (r.ok && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

    const mr = Array.isArray(r.members) ? r.members : [];
    const lat = (typeof r.alphaCr === "number" && r.alphaCr < 5) ||
                (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > r.swayLimit);
    const chordUp = (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > r.sagLimit) ||
                    (typeof r.fMin === "number" && r.fMin < 1.2);

    let changed = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const u = (mr[k] && typeof mr[k].util === "number") ? mr[k].util : null;
      let step = 0;
      if (u !== null) {
        if (u > 0.85) step = 1;
        else if (u < 0.6 && prevStep[k] !== 1) step = -1;
      }
      if (lat && LAT.indexOf(m.g) >= 0) step = Math.max(step, 1);
      if (chordUp && CH.indexOf(m.g) >= 0) step = Math.max(step, 1);
      let ni = m.idx + step;
      if (ni < 0) ni = 0;
      if (ni > SEC.length - 1) ni = SEC.length - 1;
      if (ni !== m.idx) {
        m.idx = ni;
        changed++;
      }
      prevStep[k] = step;
    }
    if (changed === 0) break;
  }

  if (best) return best.d;
  return last || build();
}

function design(site, analyse) {
  // Twin Warren girders at z = ±4.35 (top chords = deck edge nodes, bottom chords at y = -7.4),
  // top and bottom lateral bracing. Cross members are added until the frame has no internal
  // mechanism (rigidity rank check). Members are sized by utilisation, a fatigue proxy and the
  // global checks reported by analyse().
  const X = [0, 4.918, 9.836, 14.755, 19.673, 24.591, 29.509, 34.427, 39.345, 44.264, 49.182, 54.1];
  const ZL = -4.35, ZR = 4.35, H = 7.4;
  const MAT = "S690 ";
  const SEC = ["CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2",
    "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"];
  const AREA = [2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86, 17.17, 21.16, 25.65,
    26.4, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67];
  const NS = SEC.length;

  // ---- node positions ----
  const pos = {};
  const nodes = [];
  for (let i = 0; i < 12; i++) { pos["L" + i] = [X[i], 0, ZL]; pos["R" + i] = [X[i], 0, ZR]; }
  for (let i = 0; i <= 10; i++) {
    const xm = (X[i] + X[i + 1]) / 2;
    pos["BL" + i] = [xm, -H, ZL];
    pos["BR" + i] = [xm, -H, ZR];
    nodes.push({ id: "BL" + i, x: xm, y: -H, z: ZL, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xm, y: -H, z: ZR, joint: "pin" });
  }
  const names = Object.keys(pos);
  const nidx = {};
  names.forEach((n, i) => { nidx[n] = i; });
  const NC = 3 * names.length;

  // ---- base topology ----
  let mem = [];
  const add = (a, b, g, idx) => { mem.push({ a: a, b: b, g: g, idx: idx }); };
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "BL" + i, "D", 14);
    add("BL" + i, "L" + (i + 1), "D", 14);
    add("R" + i, "BR" + i, "D", 14);
    add("BR" + i, "R" + (i + 1), "D", 14);
    add("L" + i, "L" + (i + 1), "TC", 18);
    add("R" + i, "R" + (i + 1), "TC", 18);
  }
  for (let i = 0; i <= 9; i++) {
    add("BL" + i, "BL" + (i + 1), "BC", 17);
    add("BR" + i, "BR" + (i + 1), "BC", 17);
  }
  for (let i = 0; i <= 11; i++) add("L" + i, "R" + i, "ST", 8);
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + (i + 1), "TL", 8);
  for (let i = 0; i <= 10; i++) add("BL" + i, "BR" + i, "BS", 8);
  for (let i = 0; i <= 9; i++) add("BL" + i, "BR" + (i + 1), "BB", 8);

  const key = (a, b) => (a < b ? a + "|" + b : b + "|" + a);
  const conn = new Set();
  mem.forEach(m => conn.add(key(m.a, m.b)));

  // ---- rigidity (rank of member directions + bearing restraints) ----
  const buildRows = (list) => {
    const rows = [];
    for (const m of list) {
      const pa = pos[m.a], pb = pos[m.b];
      const d = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]];
      const L = Math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
      const r = new Array(NC).fill(0);
      for (let k = 0; k < 3; k++) {
        r[3 * nidx[m.a] + k] = -d[k] / L;
        r[3 * nidx[m.b] + k] = d[k] / L;
      }
      rows.push(r);
    }
    const bear = [["L0", [0, 1, 2]], ["R0", [0, 1]], ["L11", [0, 1, 2]], ["R11", [0, 1]]];
    for (const bb of bear) {
      for (const k of bb[1]) {
        const r = new Array(NC).fill(0);
        r[3 * nidx[bb[0]] + k] = 1;
        rows.push(r);
      }
    }
    return rows;
  };

  const rankOf = (rows) => {
    const A = rows.map(r => r.slice());
    const nR = A.length;
    let rank = 0;
    for (let c = 0; c < NC && rank < nR; c++) {
      let piv = -1, best = 1e-9;
      for (let r = rank; r < nR; r++) {
        const v = Math.abs(A[r][c]);
        if (v > best) { best = v; piv = r; }
      }
      if (piv < 0) continue;
      const tmp = A[rank]; A[rank] = A[piv]; A[piv] = tmp;
      const p = A[rank];
      for (let r = rank + 1; r < nR; r++) {
        const f = A[r][c] / p[c];
        if (f !== 0) {
          const row = A[r];
          for (let k = c; k < NC; k++) row[k] -= f * p[k];
        }
      }
      rank++;
    }
    return rank;
  };

  // ---- joint geometry: >= 12 deg between members, <= 12 members per joint ----
  const cos12 = Math.cos(12 * Math.PI / 180);
  const jointOK = (n, other, list) => {
    const pn = pos[n], po = pos[other];
    const u = [po[0] - pn[0], po[1] - pn[1], po[2] - pn[2]];
    const lu = Math.sqrt(u[0] * u[0] + u[1] * u[1] + u[2] * u[2]);
    let count = 0;
    for (const m of list) {
      let o = null;
      if (m.a === n) o = m.b; else if (m.b === n) o = m.a;
      if (o === null) continue;
      count++;
      const pq = pos[o];
      const v = [pq[0] - pn[0], pq[1] - pn[1], pq[2] - pn[2]];
      const lv = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
      const c = (u[0] * v[0] + u[1] * v[1] + u[2] * v[2]) / (lu * lv);
      if (c > cos12) return false;
    }
    return count < 12;
  };

  // ---- candidate cross members: bottom node to deck node, short ones first ----
  const bottoms = names.filter(n => n[0] === "B");
  const decks = names.filter(n => n[0] !== "B");
  const cands = [];
  for (const b of bottoms) {
    for (const d of decks) {
      if (conn.has(key(b, d))) continue;
      const pb = pos[b], pd = pos[d];
      const L = Math.hypot(pb[0] - pd[0], pb[1] - pd[1], pb[2] - pd[2]);
      if (L <= 12) cands.push({ a: b, b: d, len: L });
    }
  }
  cands.sort((p, q) => p.len - q.len);

  // add members until the frame carries no internal mechanism
  let cur = rankOf(buildRows(mem));
  let guard = 0;
  while (cur < NC && guard < 12) {
    let done = false;
    for (const c of cands) {
      if (conn.has(key(c.a, c.b))) continue;
      if (!jointOK(c.a, c.b, mem) || !jointOK(c.b, c.a, mem)) continue;
      const trial = mem.concat([{ a: c.a, b: c.b, g: "X", idx: 8 }]);
      const rr = rankOf(buildRows(trial));
      if (rr > cur) {
        mem = trial;
        conn.add(key(c.a, c.b));
        cur = rr;
        done = true;
        break;
      }
    }
    if (!done) break;
    guard++;
  }

  // ---- sizing loop ----
  const build = () => ({
    note: "Twin Warren girders with top/bottom lateral bracing and cross members added to remove the mechanism; S690 CHS sized per member by utilisation, fatigue proxy and global checks.",
    nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: {},
    members: mem.map(m => ({ a: m.a, b: m.b, spec: MAT + SEC[m.idx] }))
  });

  let best = null, last = null;
  for (let it = 0; it < 60; it++) {
    const d = build();
    const r = analyse(d);
    if (!r || r.error) break;
    last = d;
    if (r.ok && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

    const mr = Array.isArray(r.members) ? r.members : [];
    let maxF = 0;
    for (const e of mr) {
      if (!e) continue;
      maxF = Math.max(maxF, Math.abs(e.tension || 0), Math.abs(e.compression || 0));
    }
    const sc = maxF > 1e5 ? 1e-3 : 1; // in case forces are reported in N rather than kN

    const bump = {};
    const raise = (gs, n) => { for (const g of gs) bump[g] = Math.max(bump[g] || 0, n); };
    if (typeof r.alphaCr === "number" && r.alphaCr < 5) raise(["TC", "BC", "ST", "TL", "BS", "BB"], 1);
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > r.sagLimit) raise(["TC", "BC", "D"], 1);
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > r.swayLimit) raise(["ST", "TL", "BS", "BB"], 1);
    if (typeof r.fMin === "number" && r.fMin < 1.2) raise(["TC", "BC"], 1);
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 1) raise(["TC", "BC", "D"], 1);

    let changed = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const info = mr[k];
      const u = (info && typeof info.util === "number") ? info.util : null;
      const T = info ? Math.abs(info.tension || 0) * sc : 0;
      const C = info ? Math.abs(info.compression || 0) * sc : 0;
      const fatA = 0.5 * (T + C) / 14.3; // cm2 needed for traffic stress range (approx.)
      const curA = AREA[m.idx];
      let want = fatA;
      if (u !== null && u > 0.85) want = Math.max(want, curA * u / 0.8);
      let j = 0;
      while (j < NS - 1 && AREA[j] < want) j++;
      if (j < m.idx) {
        if (u !== null && u < 0.5) j = Math.max(j, m.idx - 1);
        else j = m.idx;
      }
      if (bump[m.g]) j = Math.max(j, m.idx + bump[m.g]);
      if (j > NS - 1) j = NS - 1;
      if (j !== m.idx) { m.idx = j; changed++; }
