        } else {
          // shrink only if the predicted utilisation stays below 0.92 * target
          const j = firstAtLeast(AREA[m.idx] * u / (0.92 * TARGET));
          ni = Math.min(j, m.idx);
          ni = Math.max(ni, m.idx - 3);
        }
      }
      if (bump[m.g]) ni = Math.max(ni, m.idx + bump[m.g]);
      if (ni > NS - 1) ni = NS - 1;
      if (ni < 0) ni = 0;
      if (ni !== m.idx) { m.idx = ni; changed++; }
    }
    if (changed === 0) break;
  }

  if (best) return best.d;
  if (bestAny) return bestAny.d;
  return last || build();
}
